@testable import EVMChain
import Foundation
import Testing
import WalletCore

/// The AI/USDG pool on Robinhood Chain (Uniswap v4), as its Initialize event names it (checked on-chain 2026-10-01).
private let aiUSDG = UniswapV4.PoolKey(currency0: "0x2E8c31162b855A2ffa90F6F8634643Ad6F111e18", currency1: "0x5fc5360d0400a0fd4f2af552add042d716f1d168",
                                       fee: 2300, tickSpacing: 23, hooks: "0x0000000000000000000000000000000000000000")
private let me = "0x90F79bf6EB2c4f870365E785982E1f101E93b906"

@Test func v4PoolKeyHashesToThePoolsId() {
    #expect(aiUSDG.id == "0x7aebd80541bfaaf23dbb6e99ce13d4d31c1a84c91414f971eadbff7db5f85995")
    #expect(!aiUSDG.hasHooks)
}

/// The same calls built by Foundry's cast (abi-encode / calldata), byte for byte.
@Test func v4CalldataMatchesCast() throws {
    #expect(try UniswapV4.execute(aiUSDG, zeroForOne: false, amountIn: 299_850_000, amountOutMinimum: Decimal(string: "1878674498454302985")!, deadline: 1_790_000_000).hex
            == "")
    #expect(try UniswapV4.quoteExactInputSingle(aiUSDG, zeroForOne: false, amount: 299_850_000).hex == "")
    #expect(try UniswapV4.permit2Approve(token: "0x5fc5360d0400a0fd4f2af552add042d716f1d168", spender: UniswapV4.robinhoodRouter,
                                         amount: 299_850_000, expiration: 1_790_001_800).hex == "87517c450000000000000000000000005fc5360d0400a0fd4f2af552add042d716f1d1680000000000000000000000008876789976decbfcbbbe364623c63652db8c09040000000000000000000000000000000000000000000000000000000011df5910000000000000000000000000000000000000000000000000000000006ab14288")
}

@Test func signerReadsTheAppsV4SwapAndPassesIt() throws {
    let data = try UniswapV4.execute(aiUSDG, zeroForOne: false, amountIn: 299_850_000, amountOutMinimum: 1_000, deadline: 1_790_000_000)
    guard case .v4Swap(let swap) = EVMCall.decode(data) else { Issue.record("not read as a v4 swap"); return }
    #expect(swap.key == aiUSDG && swap.currencyIn == aiUSDG.currency1 && swap.currencyOut == aiUSDG.currency0)
    #expect(swap.amountIn == 299_850_000 && swap.takeMin == 1_000 && swap.deadline == 1_790_000_000)
    #expect(EVMCall.decode(data).refusal(sender: me) == nil)
    #expect(EVMCall.decode(data).summary(chainId: 4663, to: UniswapV4.robinhoodRouter, value: 0).contains("Uniswap v4"))
}

@Test func signerRefusesAV4SwapThatIsntSafe() throws {
    let hooked = UniswapV4.PoolKey(currency0: aiUSDG.currency0, currency1: aiUSDG.currency1, fee: 2300, tickSpacing: 23, hooks: "0x00000000000000000000000000000000000000ff")
    #expect(EVMCall.decode(try UniswapV4.execute(hooked, zeroForOne: false, amountIn: 1, amountOutMinimum: 1, deadline: 1)).refusal(sender: me)?.contains("hooks") == true)
    #expect(EVMCall.decode(try UniswapV4.execute(aiUSDG, zeroForOne: false, amountIn: 1, amountOutMinimum: 0, deadline: 1)).refusal(sender: me)?.contains("minimum") == true)
    // SETTLE_ALL paying in the other currency than the swap's input.
    var tampered = try UniswapV4.execute(aiUSDG, zeroForOne: false, amountIn: 5, amountOutMinimum: 1, deadline: 1)
    let usdg = Data(hex: "5fc5360d0400a0fd4f2af552add042d716f1d168")!, ai = Data(hex: "2e8c31162b855a2ffa90f6f8634643ad6f111e18")!
    // The settle param is the 2nd of the three: its currency is the last USDG word before the take's AI word.
    let settleAt = tampered.range(of: usdg, options: .backwards, in: 0..<tampered.range(of: ai, options: .backwards)!.lowerBound)!
    tampered.replaceSubrange(settleAt, with: ai)
    #expect(EVMCall.decode(tampered).refusal(sender: me)?.contains("pay in") == true)
    // Any other command (a SWEEP, a TRANSFER…) is no longer this shape: read as a plain contract call, not a checked swap.
    var other = try UniswapV4.execute(aiUSDG, zeroForOne: false, amountIn: 5, amountOutMinimum: 1, deadline: 1)
    other[4 + 32 * 3 + 32] = 0x04
    if case .v4Swap = EVMCall.decode(other) { Issue.record("a SWEEP read as the app's swap") }
}

@Test func signerRefusesALoosePermit2Approval() throws {
    let now = UInt64(Date().timeIntervalSince1970)
    let ok = try UniswapV4.permit2Approve(token: "0x5fc5360d0400a0fd4f2af552add042d716f1d168", spender: UniswapV4.robinhoodRouter, amount: 1_000_000, expiration: now + 1800)
    #expect(EVMCall.decode(ok).refusal(sender: me) == nil)
    let forever = try UniswapV4.permit2Approve(token: "0x5fc5360d0400a0fd4f2af552add042d716f1d168", spender: UniswapV4.robinhoodRouter, amount: 1_000_000, expiration: now + 30 * 86_400)
    #expect(EVMCall.decode(forever).refusal(sender: me)?.contains("longer than a day") == true)
    let unlimited = try UniswapV4.permit2Approve(token: "0x5fc5360d0400a0fd4f2af552add042d716f1d168", spender: UniswapV4.robinhoodRouter,
                                                 amount: Decimal(string: "1461501637330902918203684832716283019655932542975")!, expiration: now + 1800)
    #expect(EVMCall.decode(unlimited).refusal(sender: me)?.contains("Unlimited") == true)
}
